import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // ===== GRADIENT TEXTURE =====
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 320;
  const canvasCtx = canvas.getContext('2d');

  // Draw vertical gradient: #ff4450 (0.0) -> #ff2a38 (0.55) -> #c1121f (1.0)
  const gradient = canvasCtx.createLinearGradient(0, 0, 0, canvas.height);
  gradient.addColorStop(0.0, '#ff4450');
  gradient.addColorStop(0.55, '#ff2a38');
  gradient.addColorStop(1.0, '#c1121f');
  canvasCtx.fillStyle = gradient;
  canvasCtx.fillRect(0, 0, canvas.width, canvas.height);

  // Hard seam line at 50% face height (0.01 unit wide)
  const seamPixelHeight = Math.max(1, Math.ceil((0.01 / 0.68) * canvas.height));
  const seamY = canvas.height * 0.5;
  canvasCtx.fillStyle = '#ff2a38';
  canvasCtx.fillRect(0, seamY - seamPixelHeight / 2, canvas.width, seamPixelHeight);

  const gradientTexture = new THREE.CanvasTexture(canvas);
  gradientTexture.magFilter = THREE.LinearFilter;
  gradientTexture.minFilter = THREE.LinearFilter;

  // ===== BUTTON MESH =====
  const buttonGeometry = new THREE.PlaneGeometry(2.6, 0.68);

  const buttonMaterial = new THREE.MeshStandardNodeMaterial({
    map: gradientTexture,
    emissive: 0xff2a38,
    emissiveIntensity: 1.6,
    roughness: 0.5,
    metalness: 0.35,
    clearcoat: 0.22,
    toneMapped: false,
  });

  const buttonMesh = new THREE.Mesh(buttonGeometry, buttonMaterial);
  group.add(buttonMesh);

  // ===== CONTACT SHADOW =====
  const shadowGeometry = new THREE.PlaneGeometry(2.8, 0.3);
  const shadowMaterial = new THREE.MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35,
    depthWrite: false,
  });
  const shadowMesh = new THREE.Mesh(shadowGeometry, shadowMaterial);
  shadowMesh.position.z = -0.08;
  group.add(shadowMesh);

  // ===== TEXT LABELS =====
  let labelMesh, captionMesh;

  if (ctx && ctx.fontAtlas) {
    try {
      labelMesh = ctx.fontAtlas.createText('BEGIN COMMISSION', {
        fontSize: 20,
        fontWeight: 700,
        family: 'JetBrains Mono',
        color: '#ff2a38',
        letterSpacing: 0.08,
        lineHeight: 1,
      });
      labelMesh.position.z = 0.01;
      group.add(labelMesh);
    } catch (e) {
      console.warn('Failed to create label text:', e);
    }

    try {
      captionMesh = ctx.fontAtlas.createText('NO DEPOSIT REQUIRED', {
        fontSize: 9,
        fontWeight: 400,
        family: 'JetBrains Mono',
        color: '#e8ecf2',
        letterSpacing: 0.12,
        lineHeight: 1.4,
      });
      captionMesh.position.y = -0.34 - 0.25;
      captionMesh.position.z = 0.01;
      group.add(captionMesh);
    } catch (e) {
      console.warn('Failed to create caption text:', e);
    }
  }

  // ===== SCENE PLACEMENT =====
  group.position.set(0, 0, 0);
  group.rotation.order = 'XYZ';
  group.scale.set(1, 1, 1);

  // ===== ANIMATION STATE =====
  let isHovering = false;
  let isPressed = false;
  const initialZ = 0;

  // Mount animation: weighted-settle scale 1.04 -> 1.0, 900ms
  gsap.fromTo(
    group.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: 'power4.out',
    }
  );

  // ===== EVENT HANDLERS =====
  group.userData.handlers = {
    onPointerEnter() {
      if (isPressed) return;
      isHovering = true;

      gsap.to(group.position, {
        z: initialZ + 0.06,
        duration: 0.18,
        overwrite: false,
      });

      gsap.to(buttonMaterial, {
        emissiveIntensity: 2.2,
        duration: 0.18,
        overwrite: false,
      });
    },

    onPointerLeave() {
      if (isPressed) return;
      isHovering = false;

      gsap.to(group.position, {
        z: initialZ,
        duration: 0.18,
        overwrite: false,
      });

      gsap.to(buttonMaterial, {
        emissiveIntensity: 1.6,
        duration: 0.18,
        overwrite: false,
      });
    },

    onPointerDown() {
      isPressed = true;

      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
        overwrite: false,
      });

      gsap.to(shadowMesh.material, {
        opacity: 0.5,
        duration: 0.12,
        overwrite: false,
      });
    },

    onPointerUp() {
      isPressed = false;

      gsap.to(group.scale, {
        x: 1.0,
        y: 1.0,
        duration: 0.12,
        ease: 'back.out',
        overwrite: false,
      });

      gsap.to(shadowMesh.material, {
        opacity: 0.35,
        duration: 0.12,
        overwrite: false,
      });

      if (isHovering) {
        gsap.to(group.position, {
          z: initialZ + 0.06,
          duration: 0.18,
          overwrite: false,
        });
      }
    },
  };

  // ===== CLEANUP =====
  group.userData.cleanup = () => {
    gsap.killTweensOf(group);
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(buttonMaterial);
    gsap.killTweensOf(shadowMesh.material);

    gradientTexture.dispose();
    buttonGeometry.dispose();
    buttonMaterial.dispose();
    shadowGeometry.dispose();
    shadowMaterial.dispose();

    if (labelMesh) {
      if (labelMesh.geometry) labelMesh.geometry.dispose();
      if (labelMesh.material) labelMesh.material.dispose();
    }
    if (captionMesh) {
      if (captionMesh.geometry) captionMesh.geometry.dispose();
      if (captionMesh.material) captionMesh.material.dispose();
    }
  };

  return group;
}
